mapper.select:
SELECT rcmd_rqst_id AS id,session_key_hash AS owner,cond::text AS document,rqst_at AS created_at FROM ai.rcmd_rqst
WHERE session_key_hash=#{owner}
AND cond->>'direction'=#{direction}
AND position(lower(#{search}) in lower((cond->'criteria')::text))>0
AND to_char(rqst_at,'YYYY-MM')>=#{fromYm}
AND to_char(rqst_at,'YYYY-MM')<=#{toYm}
AND (
  (cond->>'direction'='PROJECT_TO_PERSON' AND EXISTS(SELECT 1 FROM ai.rcmd_rslt s WHERE s.rcmd_rqst_id=rcmd_rqst.rcmd_rqst_id AND CASE WHEN s.rcmd_dcsn_cd='NONE' THEN 'PENDING' ELSE s.rcmd_dcsn_cd END=#{decisionStatus})) OR
  (cond->>'direction'='PERSON_TO_POSITION' AND EXISTS(SELECT 1 FROM ai.rcmd_next_rslt s WHERE s.rqst_id=rcmd_rqst.rcmd_rqst_id AND s.decision_cd=#{decisionStatus})))
ORDER BY rqst_at DESC,rcmd_rqst_id DESC

SELECT CASE WHEN a.end_dt>=#{today} OR a.asgn_stts_cd='CANCELLED' THEN -1
  WHEN EXISTS(SELECT 1 FROM asgn.asgn_chg_hist h WHERE h.asgn_id=a.asgn_id AND h.asgn_chg_ty_cd='EXTEND' AND h.fixed_yn='N') THEN 1 ELSE 0 END
FROM asgn.asgn a WHERE a.asgn_id=#{id}
